// Gambar (urut shot) + cerita -> request Claude untuk prompt Google Flow (Veo).
const item = $input.first();
const keys = Object.keys(item.binary || {}).sort((a, b) => Number(a.split('_').pop()) - Number(b.split('_').pop()));
if (!keys.length) throw new Error('Tidak ada gambar.');
const content = [];
for (const [i, k] of keys.entries()) {
  const buf = await this.helpers.getBinaryDataBuffer(0, k);
  content.push({ type: 'text', text: `Gambar shot ${i + 1}:` });
  content.push({ type: 'image', source: { type: 'base64', media_type: item.binary[k].mimeType || 'image/png', data: buf.toString('base64') } });
}
content.push({ type: 'text', text: `Alur cerita:\n${item.json['Cerita']}` });
const system = `Kamu sutradara iklan video pendek yang ahli menulis prompt Google Veo (Google Flow, mode Frames to Video).
Setiap gambar = frame awal 1 shot, sesuai urutan. Tulis 1 prompt per gambar (jumlah = ${keys.length}).
Aturan prompt (bahasa Inggris, 60-120 kata, satu paragraf):
- Mulai dengan jenis shot & gerakan kamera, lalu aksi subjek detik demi detik, lalu cahaya/suasana, lalu audio.
- Konsisten dengan gambar: jangan tambah orang/benda baru, jangan ubah warna/pakaian/lokasi.
- Klip Veo 8 detik; jika cerita minta durasi lebih pendek, tulis aksinya selesai dalam durasi itu dan sebut "cut at N seconds" di catatan.
- Ikuti instruksi cerita soal suara. Jika tanpa voice over: "No dialogue, no voice-over, no music; only natural ambient sound of ...".
- Akhiri dengan: "Photorealistic, 9:16 vertical, no text, no subtitles, no morphing."
Balas HANYA JSON: {"shots":[{"judul":"<ringkas, Indonesia>","prompt":"...","catatan":"<tips singkat Indonesia, mis. potong di detik 4>"}]}`;
return [{ json: { body: { model: 'claude-sonnet-5-5', max_tokens: 3000, system, messages: [{ role: 'user', content }] } } }];

// Susun pesan Telegram, 1 pesan per shot (mudah di-copy).
const text = $input.first().json.content[0].text;
const plan = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
const n = plan.shots.length;
return plan.shots.map((s, i) => ({ json: {
  text: `🎬 Shot ${i + 1}/${n} — ${s.judul}\nGambar: upload gambar ke-${i + 1} sebagai frame awal\n${s.catatan ? '📝 ' + s.catatan + '\n' : ''}\n${s.prompt}`,
} }));
